import{_ as n,B as l,o as s,c as r,a8 as c,a,E as o,f as i}from"./chunks/framework.CNIpabDg.js";const v=JSON.parse('{"title":"Graphical shell (executable)","description":"The graphical shell executable is the session shell that transitions from login to desktop views.","frontmatter":{"layout":"doc","docType":"explanation","description":"The graphical shell executable is the session shell that transitions from login to desktop views."},"headers":[],"relativePath":"explanation/architecture/executables/graphical_shell.md","filePath":"explanation/architecture/executables/graphical_shell.md","lastUpdated":1793145952000}'),d={name:"explanation/architecture/executables/graphical_shell.md"};function h(u,e,p,m,g,f){const t=l("CodeReference");return s(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[5]||(e[5]=c('<h1 id="graphical-shell-executable" tabindex="-1">Graphical shell (executable) <a class="header-anchor" href="#graphical-shell-executable" aria-label="Permalink to &quot;Graphical shell (executable)&quot;">​</a></h1><p>The graphical shell executable is the session shell that transitions from login to desktop views.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><ul><li>Owns login UI, session activation, and desktop/home shell composition.</li><li>Sets task-level session environment (<code>User</code>) after successful login.</li></ul><h2 id="startup-and-lifecycle" tabindex="-1">Startup and lifecycle <a class="header-anchor" href="#startup-and-lifecycle" aria-label="Permalink to &quot;Startup and lifecycle&quot;">​</a></h2><ol><li>Parses startup args (<code>--show-keyboard</code>).</li><li>Builds <code>Shell</code> with <code>Layout</code> and <code>Login</code> components.</li><li>Runs loop: layout tick -&gt; login event handling -&gt; post-login desk/home activation.</li><li>Continues desk event handling until shell loop terminates.</li></ol><h2 id="runtime-integration-points" tabindex="-1">Runtime integration points <a class="header-anchor" href="#runtime-integration-points" aria-label="Permalink to &quot;Runtime integration points&quot;">​</a></h2><ul><li><code>ExecutableTrait</code> for launcher integration.</li><li>Context-provided users manager to map the logged user ID to a user name.</li><li>Context-provided task manager to publish the session user into the task environment.</li><li>Graphics manager/LVGL wrappers for UI object/event handling.</li></ul><h2 id="data-and-control-flow-vfs-touchpoints" tabindex="-1">Data and control flow / VFS touchpoints <a class="header-anchor" href="#data-and-control-flow-vfs-touchpoints" aria-label="Permalink to &quot;Data and control flow / VFS touchpoints&quot;">​</a></h2><ul><li>Input: CLI flags and UI events.</li><li>Primary control flow is event-driven within one shell loop.</li><li>VFS touchpoints occur indirectly through components such as desktop shortcuts (implemented in submodules), not in top-level loop itself.</li></ul><h2 id="concurrency-and-event-loop-model" tabindex="-1">Concurrency and event-loop model <a class="header-anchor" href="#concurrency-and-event-loop-model" aria-label="Permalink to &quot;Concurrency and event-loop model&quot;">​</a></h2><ul><li>Single periodic loop with <code>task::sleep(Duration::from_millis(50))</code> cadence.</li><li>No internal multi-task fan-out in main loop; concurrency is delegated to underlying graphics/task systems.</li></ul><h2 id="failure-semantics" tabindex="-1">Failure semantics <a class="header-anchor" href="#failure-semantics" aria-label="Permalink to &quot;Failure semantics&quot;">​</a></h2><ul><li>Argument parse failures are printed to stderr and return non-zero.</li><li>Environment-variable update failures propagate via <code>Error::FailedToSetEnvironmentVariable</code>.</li><li>Desk/Home creation and session environment failures propagate as executable errors. <strong>Layout and Login constructors are currently unwrapped in <code>Shell::new</code> and can panic</strong> during initialization.</li></ul><h2 id="contract-vs-implementation" tabindex="-1">Contract vs implementation <a class="header-anchor" href="#contract-vs-implementation" aria-label="Permalink to &quot;Contract vs implementation&quot;">​</a></h2><ul><li><strong>Contract</strong>: graphical shell executable starts a login-driven user session loop.</li><li><strong>Current implementation</strong>: explicit login-first flow that instantiates desk/home only after authentication and publishes <code>User</code> env variable.</li></ul><h2 id="operational-limitations" tabindex="-1">Operational limitations <a class="header-anchor" href="#operational-limitations" aria-label="Permalink to &quot;Operational limitations&quot;">​</a></h2><ul><li>Loop cadence is fixed (50 ms sleep), which trades responsiveness for predictable CPU usage.</li><li>Login updates the <strong>current task&#39;s user identity</strong>, its <code>HOME</code> directory and <code>User</code> environment variable. Inheritance to child tasks follows the Task manager, not a global session registry.</li></ul><h2 id="authentication-and-session-ownership" tabindex="-1">Authentication and session ownership <a class="header-anchor" href="#authentication-and-session-ownership" aria-label="Permalink to &quot;Authentication and session ownership&quot;">​</a></h2><p><code>ShellExecutable</code> implements the native <code>ExecutableTrait</code> interface. <code>GraphicalShellArguments</code> is parsed with <code>getargs</code>, including <code>--show-keyboard</code> (<code>-k</code>). <code>--help</code> and <code>--version</code> print to stdout and exit successfully; invalid options report a nonzero status.</p><p>The login widget verifies username/password with <code>authentication::authenticate_user</code>. Upon success it:</p><ol><li>Uses <code>VirtualFileSystem::ensure_user_home(task, user)</code> to create or locate the private home directory.</li><li>Sets the Task environment&#39;s <code>HOME</code> and changes the current task&#39;s user ID.</li><li>Restores appearance through <code>graphics::appearance::restore_appearance</code>.</li><li>Resolves the username and stores it as the task&#39;s <code>User</code> environment variable.</li><li>Constructs the Desktop (<code>Desk</code>) and Home-button overlay (<code>Home</code>) before dropping the login UI.</li></ol><p><code>Desk</code> discovers desktop launchers from the shortcuts directory under <code>/configuration/shared/shortcuts</code> and launches them with the executable runtime. Its dock reflects live windows and supports window-management actions. The desktop and Home bar hold LVGL object pointers and register C callbacks; Graphics locking and window ownership are required for safe lifecycle transitions.</p><h2 id="scheduling-and-failure-boundaries" tabindex="-1">Scheduling and failure boundaries <a class="header-anchor" href="#scheduling-and-failure-boundaries" aria-label="Permalink to &quot;Scheduling and failure boundaries&quot;">​</a></h2><p>The outer session loop sleeps <strong>50 ms</strong> between handling layout, login and desktop events. Most work is event-driven within that loop; the shell itself does not implement a preemptive UI scheduler. Layout/Login construction currently uses <code>unwrap</code>; distinguish that panic path from the typed errors returned by subsequent Desk/Home construction.</p><p>Login is not an external authorization service: account persistence and password verification belong to Authentication, task identity to Task/Users, and file permissions to VFS.</p><h3 id="source-and-api-references" tabindex="-1">Source and API references <a class="header-anchor" href="#source-and-api-references" aria-label="Permalink to &quot;Source and API references&quot;">​</a></h3>',27)),a("ul",null,[a("li",null,[o(t,{repo:"applications",path:"executables/shell/graphical/src/lib.rs"}),e[0]||(e[0]=i(" — CLI, session transition and cadence.",-1))]),a("li",null,[o(t,{repo:"applications",path:"executables/shell/graphical/src/login.rs"}),e[1]||(e[1]=i(" — authentication, HOME and task identity.",-1))]),a("li",null,[o(t,{repo:"applications",path:"executables/shell/graphical/src/desk.rs"}),e[2]||(e[2]=i(" — shortcut loading, dock and window handling.",-1))]),a("li",null,[o(t,{repo:"applications",path:"executables/shell/graphical/src/home.rs"}),e[3]||(e[3]=i(" — Home gesture and overlay.",-1))])]),e[6]||(e[6]=a("h2",{id:"references",tabindex:"-1"},[i("References "),a("a",{class:"header-anchor",href:"#references","aria-label":'Permalink to "References"'},"​")],-1)),a("ul",null,[a("li",null,[o(t,{repo:"applications",path:"executables/shell/graphical"})]),e[4]||(e[4]=a("li",null,[a("a",{href:"/explanation/architecture/libraries/executable.html"},"Executable runtime crate")],-1))])])}const k=n(d,[["render",h]]);export{v as __pageData,k as default};
